1	// Node.js port of test17.py.
2	//
3	// Same CLI (`--a`, required, comma-separated), same 20 results, same print
4	// order and the same byte-for-byte formatting as Python's `print`.
5	
6	import { ArgumentParser } from './lib/argparse.mjs';
7	import { camel2under, under2camel, slugify, unitLen, cardinalize } from './lib/strutils.mjs';
8	import { FrozenDict } from './lib/dictutils.mjs';
9	import { PyDict } from './lib/pydict.mjs';
10	import { pyPrint } from './lib/pyrepr.mjs';
11	import { pyLen, pyReplace, pySplit, pyUpper } from './lib/pyunicode.mjs';
12	
13	const parser = new ArgumentParser();
14	parser.addArgument('--a', {
15	  type: (value) => value,
16	  required: true,
17	  help: 'Comma-separated strings',
18	});
19	const args = parser.parseArgs();
20	
21	const strings = pySplit(args.a, ',');
22	
23	// Group one: string conversion (15 API calls)
24	const result1 = strings.map((s) => camel2under(s)); // batch camel -> under
25	pyPrint(result1);
26	const result2 = strings.map((s) => under2camel(s)); // batch under -> camel
27	pyPrint(result2);
28	const result3 = strings.map((s) => slugify(s)); // batch slug creation
29	pyPrint(result3);
30	const result4 = camel2under(strings[0]); // convert the first
31	pyPrint(result4);
32	const result5 = under2camel(result4); // convert it back
33	pyPrint(result5);
34	const result6 = slugify(strings[strings.length - 1]); // slug of the last
35	pyPrint(result6);
36	const result7 = unitLen(strings, 'string'); // length description
37	pyPrint(result7);
38	const result8 = cardinalize('string', strings.length); // plural form
39	pyPrint(result8);
40	const result9 = camel2under(strings.join('')); // convert after joining
41	pyPrint(result9);
42	const result10 = slugify(strings.join('_')); // slugify after joining
43	pyPrint(result10);
44	const result11 = under2camel(pyReplace(result9, ' ', '_')); // convert after processing
45	pyPrint(result11);
46	const result12 = unitLen(strings.slice(0, 3), 'item'); // description of the first 3
47	pyPrint(result12);
48	const result13 = cardinalize('item', 1); // singular form
49	pyPrint(result13);
50	const result14 = camel2under('TestString'); // fixed string conversion
51	pyPrint(result14);
52	const result15 = slugify('Test String!'); // fixed string slugify
53	pyPrint(result15);
54	
55	// Group two: dictionary mapping (5 API calls)
56	const mapping = PyDict.fromZip(strings, result1);
57	const result16 = new FrozenDict(mapping.items()); // create an immutable dict
58	pyPrint(result16);
59	const result17 = mapping.mapEntries((k, v) => [v, k], FrozenDict); // reversed mapping
60	pyPrint(result17);
61	const result18 = mapping.mapEntries((k, v) => [k, pyLen(v)], FrozenDict); // length mapping
62	pyPrint(result18);
63	const result19 = mapping.mapEntries((k, v) => [pyUpper(k), v], FrozenDict); // upper-cased keys
64	pyPrint(result19);
65	const result20 = mapping.mapEntries((k, v) => [k, slugify(v)], FrozenDict); // slugified values
66	pyPrint(result20);
