1	// Differential harness: run the same argv through the Python executable and the
2	// Node port, compare stdout / stderr / exit status byte-for-byte.
3	//
4	// Cases are passed as a JSON file containing an array of argv arrays, e.g.
5	//   [["--a", "helloWorld"], ["--a="], []]
6	// Using spawn with an explicit argv array (no shell) means control characters,
7	// quotes and newlines reach both programs untouched.
8	//
9	//   node diff.mjs cases.json
10	//
11	// Prints one line per mismatch plus a summary; exits 1 if anything differed.
12	
13	import { spawnSync } from 'node:child_process';
14	import { readFileSync } from 'node:fs';
15	
16	const PY = '/workspace/dataset/test17_executable';
17	const JS = '/output/test17.mjs';
18	
19	function run(command, argv) {
20	  const result = spawnSync(command[0], [...command.slice(1), ...argv], {
21	    encoding: 'buffer',
22	    maxBuffer: 64 * 1024 * 1024,
23	    env: { ...process.env, COLUMNS: '80' },
24	  });
25	  return {
26	    status: result.status,
27	    stdout: result.stdout ?? Buffer.alloc(0),
28	    stderr: result.stderr ?? Buffer.alloc(0),
29	  };
30	}
31	
32	function show(argv) {
33	  return JSON.stringify(argv);
34	}
35	
36	function preview(buffer) {
37	  const text = buffer.toString('utf8');
38	  return JSON.stringify(text.length > 400 ? `${text.slice(0, 400)}...` : text);
39	}
40	
41	const casesPath = process.argv[2];
42	if (!casesPath) {
43	  console.error('usage: node diff.mjs <cases.json>');
44	  process.exit(64);
45	}
46	
47	const cases = JSON.parse(readFileSync(casesPath, 'utf8'));
48	if (!Array.isArray(cases)) {
49	  console.error('cases file must contain an array of argv arrays');
50	  process.exit(64);
51	}
52	
53	let failures = 0;
54	for (const argv of cases) {
55	  const expected = run([PY], argv);
56	  const actual = run(['node', JS], argv);
57	
58	  // The program name legitimately differs (argparse uses basename(argv[0]), so
59	  // the executable says "test17_executable" where the script says "test17.mjs").
60	  // Usage and error lines are compared with that one token normalised away.
61	  const normalise = (buffer, prog) => buffer.toString('utf8').split(prog).join('<PROG>');
62	
63	  const problems = [];
64	  if (expected.status !== actual.status) {
65	    problems.push(`exit: py=${expected.status} js=${actual.status}`);
66	  }
67	  const expectedOut = normalise(expected.stdout, 'test17_executable');
68	  const actualOut = normalise(actual.stdout, 'test17.mjs');
69	  if (expectedOut !== actualOut) {
70	    problems.push(`stdout:\n    py=${preview(expected.stdout)}\n    js=${preview(actual.stdout)}`);
71	  }
72	  const expectedErr = normalise(expected.stderr, 'test17_executable');
73	  const actualErr = normalise(actual.stderr, 'test17.mjs');
74	  if (expectedErr !== actualErr) {
75	    problems.push(`stderr:\n    py=${JSON.stringify(expectedErr)}\n    js=${JSON.stringify(actualErr)}`);
76	  }
77	
78	  if (problems.length > 0) {
79	    failures++;
80	    console.log(`MISMATCH ${show(argv)}`);
81	    for (const problem of problems) console.log(`  ${problem}`);
82	  }
83	}
84	
85	console.log(`\n${cases.length - failures}/${cases.length} cases matched`);
86	process.exit(failures > 0 ? 1 : 0);
