1	// boltons.dictutils -- the immutable mapping.
2	//
3	// Behaviour reproduced from the reference program: printing a FrozenDict yields
4	// `FrozenDict(` + the plain dict repr + `)`, e.g.
5	//   FrozenDict({'helloWorld': 'hello_world', 'foo_bar': 'foo_bar'})
6	// Empty input therefore prints `FrozenDict({})`.
7	//
8	// The real FrozenDict rejects every mutating operation with a TypeError naming
9	// the class, so the same guard is kept here even though this port never trips it.
10	
11	import { PyDict } from './pydict.mjs';
12	
13	export class FrozenDict extends PyDict {
14	  __repr__() {
15	    return `${this.constructor.name}(${this.reprBody()})`;
16	  }
17	
18	  set() {
19	    this._raiseFrozenTypeError();
20	  }
21	
22	  _raiseFrozenTypeError() {
23	    throw new TypeError(`${this.constructor.name} object is immutable`);
24	  }
25	}
