1	// An insertion-ordered mapping with Python `dict` semantics.
2	//
3	// A JS `Map` already matches Python's dict on the two points that matter for
4	// output: iteration follows first-insertion order, and re-assigning an existing
5	// key updates the value *in place* without moving it. So `dict(zip(...))` over
6	// input with repeats collapses to a shorter dict that keeps the earliest
7	// position of each key, exactly as the reference program shows.
8	
9	import { pyRepr } from './pyrepr.mjs';
10	
11	export class PyDict {
12	  constructor(entries = []) {
13	    this._map = new Map();
14	    for (const [key, value] of entries) {
15	      this._map.set(key, value);
16	    }
17	  }
18	
19	  /** Python `dict(zip(keys, values))`: pairs up to the shorter of the two. */
20	  static fromZip(keys, values) {
21	    const length = Math.min(keys.length, values.length);
22	    const entries = [];
23	    for (let i = 0; i < length; i++) {
24	      entries.push([keys[i], values[i]]);
25	    }
26	    return new this(entries);
27	  }
28	
29	  /** Python `len(dict)`. */
30	  get size() {
31	    return this._map.size;
32	  }
33	
34	  /** Python `dict.items()`, as an array of `[key, value]` pairs. */
35	  items() {
36	    return [...this._map.entries()];
37	  }
38	
39	  /** Python `dict.keys()`. */
40	  keys() {
41	    return [...this._map.keys()];
42	  }
43	
44	  /** Python `dict.values()`. */
45	  values() {
46	    return [...this._map.values()];
47	  }
48	
49	  get(key) {
50	    return this._map.get(key);
51	  }
52	
53	  has(key) {
54	    return this._map.has(key);
55	  }
56	
57	  set(key, value) {
58	    this._map.set(key, value);
59	    return this;
60	  }
61	
62	  /**
63	   * Python dict-comprehension over this mapping: `{f(k): g(v) for k, v in ...}`.
64	   * Later collisions overwrite earlier ones, matching Python.
65	   */
66	  mapEntries(fn, DictClass = PyDict) {
67	    return new DictClass(this.items().map(([key, value]) => fn(key, value)));
68	  }
69	
70	  /** The `{...}` part of Python's dict repr. */
71	  reprBody() {
72	    const inner = this.items()
73	      .map(([key, value]) => `${pyRepr(key)}: ${pyRepr(value)}`)
74	      .join(', ');
75	    return `{${inner}}`;
76	  }
77	
78	  __repr__() {
79	    return this.reprBody();
80	  }
81	}
