1	// Python `repr()` / `print()` reproduction.
2	//
3	// CPython's string repr, confirmed against the reference program:
4	//   * The quote is `'` unless the text contains `'` and no `"`, in which case
5	//     it becomes `"` -- so `q'"r` reprs as `'q\'"r'` but `it's` reprs as `"it's"`.
6	//   * `\\`, the active quote, `\t`, `\n` and `\r` get short escapes.
7	//   * Anything below U+0020, plus U+007F, becomes `\xXX`.
8	//   * Everything else printable (per `str.isprintable()`) is emitted literally,
9	//     including astral characters -- U+1F600 stays a literal emoji.
10	//   * Remaining unprintables widen by magnitude: `\xXX` below U+0100,
11	//     `\uXXXX` below U+10000, `\UXXXXXXXX` above -- hence `\xa0` and `​`.
12	
13	import { codePoints, isPrintableCodePoint } from './pyunicode.mjs';
14	
15	function hex(code, width) {
16	  return code.toString(16).padStart(width, '0');
17	}
18	
19	/** Python `repr()` of a `str`. */
20	export function reprStr(str) {
21	  const quote = str.includes("'") && !str.includes('"') ? '"' : "'";
22	  let out = quote;
23	  for (const cp of codePoints(str)) {
24	    const code = cp.codePointAt(0);
25	    if (cp === quote || cp === '\\') {
26	      out += `\\${cp}`;
27	    } else if (cp === '\t') {
28	      out += '\\t';
29	    } else if (cp === '\n') {
30	      out += '\\n';
31	    } else if (cp === '\r') {
32	      out += '\\r';
33	    } else if (code < 0x20 || code === 0x7f) {
34	      out += `\\x${hex(code, 2)}`;
35	    } else if (code < 0x7f) {
36	      out += cp;
37	    } else if (isPrintableCodePoint(cp)) {
38	      out += cp;
39	    } else if (code <= 0xff) {
40	      out += `\\x${hex(code, 2)}`;
41	    } else if (code <= 0xffff) {
42	      out += `\\u${hex(code, 4)}`;
43	    } else {
44	      out += `\\U${hex(code, 8)}`;
45	    }
46	  }
47	  return out + quote;
48	}
49	
50	/** Python `repr()` of an `int`. */
51	export function reprInt(value) {
52	  if (!Number.isInteger(value)) {
53	    throw new TypeError(`not an integer: ${value}`);
54	  }
55	  return String(value);
56	}
57	
58	/**
59	 * Python `repr()` of any value in the small model this port needs:
60	 * `str`, `int`, `list` (a JS array) and objects that provide `__repr__`.
61	 */
62	export function pyRepr(value) {
63	  if (typeof value === 'string') return reprStr(value);
64	  if (typeof value === 'number') return reprInt(value);
65	  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
66	  if (value !== null && typeof value.__repr__ === 'function') {
67	    return value.__repr__();
68	  }
69	  throw new TypeError(`no repr for ${typeof value}`);
70	}
71	
72	/** Python `str()`: strings pass through untouched, everything else reprs. */
73	export function pyStr(value) {
74	  if (typeof value === 'string') return value;
75	  return pyRepr(value);
76	}
77	
78	/** Python `print(value)`: `str()` the value, terminate with a single newline. */
79	export function pyPrint(value) {
80	  process.stdout.write(`${pyStr(value)}\n`);
81	}
