1	// Python-level Unicode/text primitives.
2	//
3	// Everything here was derived from the observed behaviour of the reference
4	// program (CPython 3.12 semantics), not from reading CPython source:
5	//   * `len()` / iteration count Unicode code points, while JS strings are
6	//     sequences of UTF-16 units.
7	//   * `str.capitalize()` title-cases the first code point (NOT upper-cases it)
8	//     and lower-cases the remainder: U+00DF 'x' -> 'Ssx', U+01F3 'y' -> U+01F2
9	//     'y', U+1F80 'q' -> U+1F88 'q'.
10	//   * `str.isprintable()` drives `repr()` escaping.
11	//   * `str.strip()` uses Python's own whitespace set, which differs from
12	//     JS `String.prototype.trim()` at both ends.
13	//
14	// The source of this module is deliberately pure ASCII: every non-ASCII string
15	// is built from numeric code points so the data cannot be silently altered by
16	// an editor, a transcoding step, or a copy/paste.
17	
18	/** Convenience: build a string from a list of code point numbers. */
19	function chars(...codes) {
20	  return String.fromCodePoint(...codes);
21	}
22	
23	/** Split a string into its Unicode code points (Python iteration order). */
24	export function codePoints(str) {
25	  return Array.from(str);
26	}
27	
28	/** Python `len(str)`: number of code points. */
29	export function pyLen(str) {
30	  return codePoints(str).length;
31	}
32	
33	/** Python `str.lower()`. Full mapping, including Greek final-sigma context. */
34	export function pyLower(str) {
35	  return str.toLowerCase();
36	}
37	
38	/** Python `str.upper()`. Full mapping, so U+00DF -> 'SS'. */
39	export function pyUpper(str) {
40	  return str.toUpperCase();
41	}
42	
43	// ---------------------------------------------------------------------------
44	// Title-case mapping
45	// ---------------------------------------------------------------------------
46	// For nearly every code point the title form equals the upper form. Where the
47	// upper form expands to several code points, the title form is the upper form
48	// with everything after the leading code point lower-cased (U+00DF -> 'SS' ->
49	// 'Ss'; U+FB00 -> 'FF' -> 'Ff'). Two families break that rule and need
50	// explicit data:
51	//   1. the Latin digraphs, whose title form is a third, distinct code point;
52	//   2. the Greek letters with ypogegrammeni, whose title form keeps the
53	//      combining/prosgegrammeni shape instead of expanding to a capital iota.
54	// One lone code point also breaks it: U+0149 titles to U+02BC U+004E, but its
55	// upper form starts with an uncased modifier letter, so the "lower-case the
56	// tail" rule would wrongly yield U+02BC U+006E.
57	const TITLE_EXCEPTIONS = new Map();
58	
59	// Latin digraphs DZ, LJ, NJ and DZ-with-caron. Each is a run of three code
60	// points (upper, title, lower) that all title to the middle one.
61	for (const upper of [0x01c4, 0x01c7, 0x01ca, 0x01f1]) {
62	  const title = chars(upper + 1);
63	  TITLE_EXCEPTIONS.set(chars(upper), title);
64	  TITLE_EXCEPTIONS.set(chars(upper + 1), title);
65	  TITLE_EXCEPTIONS.set(chars(upper + 2), title);
66	}
67	
68	// U+0149 LATIN SMALL LETTER N PRECEDED BY APOSTROPHE -> U+02BC U+004E.
69	TITLE_EXCEPTIONS.set(chars(0x0149), chars(0x02bc, 0x004e));
70	
71	// The 1F80..1FAF runs: each block of 8 lower-case forms titles to the 8
72	// capital-with-prosgegrammeni forms that follow it, which title to themselves.
73	for (const base of [0x1f80, 0x1f90, 0x1fa0]) {
74	  for (let i = 0; i < 8; i++) {
75	    const title = chars(base + 8 + i);
76	    TITLE_EXCEPTIONS.set(chars(base + i), title);
77	    TITLE_EXCEPTIONS.set(title, title);
78	  }
79	}
80	
81	// Greek vowels with ypogegrammeni outside those runs. The title form keeps the
82	// combining ypogegrammeni U+0345 (or collapses to the single prosgegrammeni
83	// code point) where the upper form would expand to a capital iota U+0399.
84	for (const [source, title] of [
85	  [[0x1fb2], [0x1fba, 0x0345]],
86	  [[0x1fb3], [0x1fbc]],
87	  [[0x1fb4], [0x0386, 0x0345]],
88	  [[0x1fb7], [0x0391, 0x0342, 0x0345]],
89	  [[0x1fbc], [0x1fbc]],
90	  [[0x1fc2], [0x1fca, 0x0345]],
91	  [[0x1fc3], [0x1fcc]],
92	  [[0x1fc4], [0x0389, 0x0345]],
93	  [[0x1fc7], [0x0397, 0x0342, 0x0345]],
94	  [[0x1fcc], [0x1fcc]],
95	  [[0x1ff2], [0x1ffa, 0x0345]],
96	  [[0x1ff3], [0x1ffc]],
97	  [[0x1ff4], [0x038f, 0x0345]],
98	  [[0x1ff7], [0x03a9, 0x0342, 0x0345]],
99	  [[0x1ffc], [0x1ffc]],
100	]) {
101	  TITLE_EXCEPTIONS.set(chars(...source), chars(...title));
102	}
103	
104	/** Python's full title mapping for a single code point. */
105	export function titleCodePoint(cp) {
106	  const known = TITLE_EXCEPTIONS.get(cp);
107	  if (known !== undefined) return known;
108	  const upper = cp.toUpperCase();
109	  const parts = codePoints(upper);
110	  if (parts.length <= 1) return upper;
111	  return parts[0] + parts.slice(1).join('').toLowerCase();
112	}
113	
114	/** Python `str.capitalize()`. */
115	export function pyCapitalize(str) {
116	  const cps = codePoints(str);
117	  if (cps.length === 0) return '';
118	  return titleCodePoint(cps[0]) + cps.slice(1).join('').toLowerCase();
119	}
120	
121	const CASED_RE = /\p{Cased}/u;
122	
123	/** Python `str.title()`: title-case the head of every run of cased characters. */
124	export function pyTitle(str) {
125	  let out = '';
126	  let previousIsCased = false;
127	  for (const cp of codePoints(str)) {
128	    out += previousIsCased ? cp.toLowerCase() : titleCodePoint(cp);
129	    previousIsCased = CASED_RE.test(cp);
130	  }
131	  return out;
132	}
133	
134	// ---------------------------------------------------------------------------
135	// str.isprintable()
136	// ---------------------------------------------------------------------------
137	// Python treats the separator and "other" categories as unprintable, with the
138	// plain space U+0020 carved out as an explicit exception. `\p{Cn}` (unassigned)
139	// is part of that set, which is why unassigned code points also escape.
140	const UNPRINTABLE_RE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
141	
142	/** Python `str.isprintable()` for a single code point. */
143	export function isPrintableCodePoint(cp) {
144	  if (cp === ' ') return true;
145	  return !UNPRINTABLE_RE.test(cp);
146	}
147	
148	// ---------------------------------------------------------------------------
149	// str.strip()
150	// ---------------------------------------------------------------------------
151	// Python's whitespace set: \t\n\v\f\r, the file/group/record/unit separators
152	// U+001C..U+001F, space, NEL, NBSP and the Unicode space separators. Notably it
153	// does NOT include U+FEFF (which JS `trim()` strips) and DOES include
154	// U+001C..U+001F and U+0085 (which JS `trim()` keeps).
155	const PY_WHITESPACE = new Set(
156	  [
157	    0x09, 0x0a, 0x0b, 0x0c, 0x0d, // tab, newline, vtab, formfeed, return
158	    0x1c, 0x1d, 0x1e, 0x1f, // file/group/record/unit separators
159	    0x20, // space
160	    0x85, // NEL
161	    0xa0, // NBSP
162	    0x1680, // OGHAM SPACE MARK
163	    0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
164	    0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
165	    0x2028, // LINE SEPARATOR
166	    0x2029, // PARAGRAPH SEPARATOR
167	    0x202f, // NARROW NO-BREAK SPACE
168	    0x205f, // MEDIUM MATHEMATICAL SPACE
169	    0x3000, // IDEOGRAPHIC SPACE
170	  ].map((cp) => chars(cp)),
171	);
172	
173	/** Python `str.strip()` with no argument. */
174	export function pyStrip(str) {
175	  const cps = codePoints(str);
176	  let start = 0;
177	  let end = cps.length;
178	  while (start < end && PY_WHITESPACE.has(cps[start])) start++;
179	  while (end > start && PY_WHITESPACE.has(cps[end - 1])) end--;
180	  return cps.slice(start, end).join('');
181	}
182	
183	/**
184	 * Python `str.split(sep)` for a non-empty separator. JS `String.split` already
185	 * agrees for this case (both keep empty leading/trailing fields), so this is a
186	 * named alias that documents the intent at the call sites.
187	 */
188	export function pySplit(str, sep) {
189	  if (sep === '') throw new Error('empty separator');
190	  return str.split(sep);
191	}
192	
193	/** Python `str.replace(old, new)`: replaces every occurrence, not just the first. */
194	export function pyReplace(str, oldSub, newSub) {
195	  return str.split(oldSub).join(newSub);
196	}
197

1	// boltons.strutils -- the string helpers this program uses.
2	//
3	// Reverse-engineered from the reference program's observable behaviour. The
4	// non-obvious findings, each confirmed against the executable:
5	//
6	//   camel2under  Inserts `_` before an ASCII capital that either follows an
7	//                ASCII lower-case letter or digit, or precedes an ASCII
8	//                lower-case letter (and is not at position 0), then lower-cases
9	//                everything. The character classes are ASCII-only, so
10	//                'hello,World' -> 'hello _world' keeps the space and gains an
11	//                underscore, while accented text is merely lower-cased:
12	//                U+00F4 + 'W' + U+00F6 never splits.
13	//                  'ABCDef' -> 'abc_def'   'x1Y2z' -> 'x1_y2z'
